+                model.push((class, arrival));
+                if (state >> 40) % 2 == 0 {
+                    let first = model.iter().map(|(class, _)| *class).min().unwrap();
+                    let lesser = model.iter().filter(|(class, _)| *class > first).map(|(_, at)| *at).min();
