+                    bypassed = if lesser.is_none() || lesser == Some(want) { 0 } else { bypassed + 1 };
+                    model.retain(|(_, at)| *at != want);
+                    assert_eq!(queue.next(), Some(want), "seed {seed}, arrival {arrival}");
+                }
+            }
+        }
+    }
